const input = $input.first().json || {};

function compactJson(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch (error) {
    return String(value);
  }
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C4-L",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        lead_qualification: null,
        c4e_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C4-L will not qualify lead when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "qualify_lead") {
  return fail({
    code: "QUALIFICATION_NOT_REQUESTED",
    message: "source.next_action is not qualify_lead.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.client_ai_profile || typeof config.client_ai_profile !== "object") {
  return fail({
    code: "MISSING_CLIENT_AI_PROFILE",
    message: "config.client_ai_profile is required."
  });
}

if (!config.client_ai_profile.client_profile || !config.client_ai_profile.lead_qualification_rules) {
  return fail({
    code: "INCOMPLETE_CLIENT_AI_PROFILE",
    message: "client_ai_profile must include at least client_profile and lead_qualification_rules."
  });
}

if (!config.score_thresholds || typeof config.score_thresholds !== "object") {
  return fail({
    code: "MISSING_SCORE_THRESHOLDS",
    message: "config.score_thresholds is required."
  });
}

if (!config.llm || typeof config.llm !== "object") {
  return fail({
    code: "MISSING_LLM_CONFIG",
    message: "config.llm is required."
  });
}

if (!config.llm.provider || !config.llm.endpoint || !config.llm.model) {
  return fail({
    code: "INCOMPLETE_LLM_CONFIG",
    message: "config.llm must include provider, endpoint, and model."
  });
}

if (config.llm.provider !== "groq") {
  return fail({
    code: "UNSUPPORTED_LLM_PROVIDER",
    message: "C4-L v1 demo supports provider = groq.",
    details: [{ provider: config.llm.provider }]
  });
}

const sourcePayload = source.payload || {};
const profile = config.client_ai_profile;
const rules = profile.lead_qualification_rules || {};
const thresholds = config.score_thresholds || {};

const systemInstruction = [
  "You are a client-configured AI lead qualification component inside an automation workflow.",
  "You qualify leads using only the provided lead payload, client profile, audience profile, and qualification rules.",
  "You do not send emails, update CRM records, or make final sales decisions.",
  "Do not invent facts, budget, company details, urgency, or intent.",
  "Return valid JSON only. Do not include markdown fences."
].join(" ");

const outputSchema = {
  lead_qualification: {
    status: "qualified | possible_fit | unqualified | manual_review",
    score: "number from 0 to 100",
    priority: "high | medium | low",
    fit: "good_fit | possible_fit | bad_fit | needs_review",
    reasons: ["string"],
    disqualifiers: ["string"],
    manual_review_required: "boolean",
    confidence: "high | medium | low",
    recommended_next_action: "generate_email_draft | manual_review | do_not_contact | nurture"
  }
};

const userContent = [
  "LEAD PAYLOAD",
  compactJson(sourcePayload),
  "",
  "UPSTREAM CONTEXT",
  compactJson({
    suppression: source.suppression || null,
    dedupe: source.dedupe || null,
    metadata: source.metadata || null,
    source_component: source.component_id || null
  }),
  "",
  "CLIENT AI PROFILE",
  compactJson(profile),
  "",
  "QUALIFICATION RULES",
  compactJson({
    qualified_criteria: rules.qualified_criteria || [],
    unqualified_criteria: rules.unqualified_criteria || [],
    high_score_signals: rules.high_score_signals || [],
    medium_score_signals: rules.medium_score_signals || [],
    low_score_signals: rules.low_score_signals || [],
    automatic_disqualifiers: rules.automatic_disqualifiers || [],
    manual_review_triggers: rules.manual_review_triggers || [],
    risk_manual_review_triggers: profile.risk_boundaries?.manual_review_triggers || []
  }),
  "",
  "SCORE THRESHOLDS",
  compactJson({
    qualified: thresholds.qualified,
    possible_fit: thresholds.possible_fit,
    manual_review: thresholds.manual_review
  }),
  "",
  "DECISION RULES",
  compactJson({
    qualified: "Use when lead clearly matches ICP, has valid contact/business context, and has clear need.",
    possible_fit: "Use when there is some fit but weaker urgency/context.",
    unqualified: "Use when clear bad-fit/disqualifier exists.",
    manual_review: "Use when lead may be valuable but duplicate, consent, intent, or context is uncertain."
  }),
  "",
  "OUTPUT JSON SCHEMA",
  compactJson(outputSchema),
  "",
  "Return JSON only with the key lead_qualification."
].join("\n");

const body = {
  model: config.llm.model,
  messages: [
    {
      role: "system",
      content: systemInstruction
    },
    {
      role: "user",
      content: userContent
    }
  ],
  temperature: config.llm.temperature ?? 0.1,
  max_tokens: config.llm.max_tokens ?? 700,
  response_format: {
    type: "json_object"
  }
};

return [
  {
    json: {
      stop_before_http: false,
      request: {
        provider: config.llm.provider,
        endpoint: config.llm.endpoint,
        body
      },
      context: {
        component_id: "C4-L",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        qualification_mode: config.qualification_mode || "rules_plus_ai",
        client_ai_profile: profile,
        score_thresholds: thresholds,
        source_result: source,
        default_next_action: config.default_next_action || "generate_email_draft"
      }
    }
  }
];

const llmOutput = $input.first().json || {};
const prepared = $("Prepare Lead Qualification Request").first().json;
const context = prepared.context;

const content =
  llmOutput.choices?.[0]?.message?.content ??
  llmOutput.choices?.[0]?.text ??
  null;

let parsedJson = null;
let parseError = null;

if (content) {
  try {
    parsedJson = JSON.parse(content);
  } catch (error) {
    parseError = error.message;
  }
}

const leadQualification = parsedJson?.lead_qualification || null;

if (!leadQualification) {
  return [
    {
      json: {
        success: false,
        component_id: context.component_id,
        component_version: context.component_version,
        event_id: context.event_id,
        event_type: context.event_type,
        lead_qualification: null,
        c4e_handoff: null,
        manual_review_handoff: null,
        source_result: context.source_result,
        error: {
          code: parseError ? "QUALIFICATION_PARSE_FAILED" : "MISSING_LEAD_QUALIFICATION",
          message: parseError
            ? "LLM response could not be parsed as JSON."
            : "LLM response did not include lead_qualification.",
          details: [{ raw_content: content, parse_error: parseError }]
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

const decision = leadQualification.status || "manual_review";
const recommended = leadQualification.recommended_next_action || "manual_review";
const manualReviewRequired =
  leadQualification.manual_review_required === true ||
  decision === "manual_review" ||
  recommended === "manual_review";

const normalizedQualification = {
  status: decision,
  score: Number(leadQualification.score ?? 0),
  priority: leadQualification.priority || "medium",
  fit: leadQualification.fit || "needs_review",
  reasons: Array.isArray(leadQualification.reasons) ? leadQualification.reasons : [],
  disqualifiers: Array.isArray(leadQualification.disqualifiers) ? leadQualification.disqualifiers : [],
  manual_review_required: manualReviewRequired,
  confidence: leadQualification.confidence || "medium",
  recommended_next_action: recommended,
  provider: prepared.request.provider,
  model: prepared.request.body.model,
  usage: llmOutput.usage || null,
  finish_reason: llmOutput.choices?.[0]?.finish_reason || null
};

let c4eHandoff = null;
let manualReviewHandoff = null;
let nextAction = recommended;

if (decision === "qualified" && recommended === "generate_email_draft" && !manualReviewRequired) {
  c4eHandoff = {
    next_component: "C4-E",
    input: {
      success: true,
      component_id: "C4-L",
      component_version: "v1",
      event_id: context.event_id,
      event_type: context.event_type,
      payload: context.source_result.payload || {},
      metadata: {
        source_component: context.source_result.component_id || null,
        qualification_status: normalizedQualification.status,
        qualification_score: normalizedQualification.score,
        qualification_priority: normalizedQualification.priority
      },
      lead_qualification: normalizedQualification,
      error: null,
      next_action: "generate_email_draft"
    },
    config: {
      email_type: "first_response",
      email_goal: "Respond to a qualified lead and offer the most relevant next step.",
      recipient_context: "Qualified inbound lead.",
      client_ai_profile: context.client_ai_profile,
      llm: {
        provider: prepared.request.provider,
        endpoint: prepared.request.endpoint,
        model: prepared.request.body.model,
        temperature: 0.2,
        max_tokens: 700
      },
      default_next_action: "package_draft_for_approval"
    }
  };

  nextAction = "generate_email_draft";
} else if (manualReviewRequired || decision === "manual_review") {
  manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C4-L",
      component_version: "v1",
      event_id: context.event_id,
      event_type: context.event_type,
      lead_qualification: normalizedQualification,
      source_result: context.source_result,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "lead_qualification_review",
      review_reason: "Lead qualification requires manual review",
      reviewer_email: context.client_ai_profile?.approval_rules?.primary_reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "sales",
      priority: normalizedQualification.priority || "normal",
      allowed_actions: ["mark_qualified", "mark_unqualified", "request_more_info", "nurture"],
      default_next_action: "notify_reviewer"
    }
  };

  nextAction = "manual_review";
} else if (decision === "unqualified" || recommended === "do_not_contact") {
  nextAction = "do_not_contact";
} else if (decision === "possible_fit" || recommended === "nurture") {
  nextAction = "nurture";
}

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      lead_qualification: normalizedQualification,
      c4e_handoff: c4eHandoff,
      manual_review_handoff: manualReviewHandoff,
      source_result: context.source_result,
      error: null,
      next_action: nextAction
    }
  }
];

const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      lead_qualification: prepared.lead_qualification,
      c4e_handoff: prepared.c4e_handoff,
      manual_review_handoff: prepared.manual_review_handoff,
      source_result: prepared.source_result,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];
